31:     pub fn put(&mut self, key: &str, val: i64) {
32:         if let Some(e) = self.vals.iter_mut().find(|(k, _)| k == key) {
33:             e.1 = val;
34:             self.touch(key);
35:             return;
36:         }
37:         if self.vals.len() == self.cap {
38:             let evict = self.order.remove(0);
39:             self.vals.retain(|(k, _)| *k != evict);
40:         }
41:         self.vals.push((key.to_string(), val));
42:         self.order.push(key.to_string());
43:     }
